<!DOCTYPE html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><title>My Tasks | AppTasker</title><style>body{margin:0;background:#f5f7fb;font-family:Inter,system-ui;color:#182230}.w{max-width:1000px;margin:auto;padding:24px 16px}.back{color:#526df5;text-decoration:none;font-weight:800}.card{background:#fff;border:1px solid #e7eaf0;border-radius:18px;padding:20px;margin-top:18px}.row{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px;padding:15px 0;border-bottom:1px solid #eee}.muted{color:#667085;font-size:13px}@media(max-width:600px){.row{grid-template-columns:1fr}}</style></head><body><main class="w"><a class="back" href="{{ route('worker.dashboard') }}">← Dashboard</a><h1>My Tasks</h1><section class="card">@forelse($workerTasks as $item)<div class="row"><div><strong>{{ $item->task->title }}</strong><div class="muted">{{ optional($item->started_at)->format('M d, Y · h:i A') }}</div></div><div>Reward<br><strong>${{ number_format((float)$item->task->reward,2) }}</strong></div><div>Status<br><strong>{{ ucfirst($item->submission?->status ?: $item->status) }}</strong></div></div>@empty<p>No task history yet.</p>@endforelse</section><div style="margin-top:18px">{{ $workerTasks->links() }}</div></main></body></html>